          "detailMarkdown": "## 6843 進典 深度法說分析\n\n### 一頁結論\n- 展望評價：中性觀望（50 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：缺少可評估的展望內容。\n- 判讀：目前資訊偏中性，正向題材與不確定因素並存，需等待更明確的量化指標。 \n\n### 營運與財務重點\n- **成立與規模**：簡報揭露公司成立於 **1975 年**，資本額 **新台幣 3.33 億元**，員工 **210 人**。\n- **生產基地**：簡報列示台灣總部/工廠、大陸、美國三地生產基地；轉錄另提及日本可能成為第三個海外生產據點，**需人工確認**。\n- **產線與投入**：轉錄指出美國休士頓已有 **兩條生產線**，用於自動控制與儀表閥門；並提到當地投入成本高。\n- **營運結構**：轉錄表示目前營收結構傾向 **電力、其他、石化** 三分天下，且石化比重下滑。\n- **財務數字**：本次簡報未揭露完整損益表、毛利率、營收、獲利或資本支出數據，**未揭露**。\n\n### 展望與成長利基\n- **市場方向**：公司持續強調半導體氣體供應、AI 資料中心液冷/冷卻、燃氣電廠 HRSG 關鍵閥門為三大成長引擎。\n- **電力需求**：轉錄提到美國燃氣電廠未來三到五年需求可能達 **60GW～100GW**，公司將持續切入相關供應鏈，**需人工確認**。\n- **海外成長**：簡報與轉錄均提及北美、日本、歐洲與東南亞市場的拓展，尤其美國製造與在地交貨能力被視為重點。\n- **產品升級**：公司希望由單一閥件供應，進一步走向 **控制系統整合** 與整體解決方案。\n- **新應用場景**：除半導體與電力外，亦提及地熱、氫能源、頁岩油氣、特化、製藥、鋼鐵等應用。\n\n### 產品、客戶與市場位置\n- **生產基地**：簡報列示台灣總部/工廠、大陸、美國三地生產基地；轉錄另提及日本可能成為第三個海外生產據點，**需人工確認**。\n- **產線與投入**：轉錄指出美國休士頓已有 **兩條生產線**，用於自動控制與儀表閥門；並提到當地投入成本高。\n- **市場方向**：公司持續強調半導體氣體供應、AI 資料中心液冷/冷卻、燃氣電廠 HRSG 關鍵閥門為三大成長引擎。\n- **電力需求**：轉錄提到美國燃氣電廠未來三到五年需求可能達 **60GW～100GW**，公司將持續切入相關供應鏈，**需人工確認**。\n- **海外成長**：簡報與轉錄均提及北美、日本、歐洲與東南亞市場的拓展，尤其美國製造與在地交貨能力被視為重點。\n- **產品升級**：公司希望由單一閥件供應，進一步走向 **控制系統整合** 與整體解決方案。\n\n### 風險與不確定性\n- **地緣風險**：轉錄提到中東部分案件因戰事而延遲，顯示專案時程存在不確定性。\n- **產能限制**：轉錄多次提到即使取得訂單，仍受限於公司供應與交期能力，屬營運風險。\n- **高投入成本**：美國設廠與在地團隊成本偏高，可能對短期獲利形成壓力。\n- **客戶集中/認證門檻**：進入半導體、電力與資料中心供應鏈需取得 AVL/認證，前期導入時間長。\n- **市場波動**：石化與部分海外市場需求有循環性，受景氣與政策影響明顯。\n- **需人工確認：日本第三個海外生產基地**\n- 簡報僅列出台灣、大陸、美國生產基地；轉錄提到日本可能成為第三個海外基地。\n- **需人工確認：HRSG 合作夥伴名稱**\n\n### Q&A 與管理層口氣\n- **Q：電力（energy）營收比重是否會提升？**\n- **Q：美國電力市場後續需求如何？**\n- **Q：公司為何強調 AI？**\n- **Q：有哪些重要客戶或供應資格？**\n- **其他**：本場簡報大量篇幅為產品、應用與市場案例展示，未見完整財務 QA 列表，**未揭露**。\n\n### 評分利基點\n- 加分主因：**產線與投入**：轉錄指出美國休士頓已有 **兩條生產線**，用於自動控制與儀表閥門；並提到當地投入成本高。；**市場方向**：公司持續強調半導體氣體供應、AI 資料中心液冷/冷卻、燃氣電廠 HRSG 關鍵閥門為三大成長引擎。；**電力需求**：轉錄提到美國燃氣電廠未來三到五年需求可能達 **60GW～100GW**，公司將持續切入相關供應鏈，**需人工確認**。。\n- 扣分或保留：**地緣風險**：轉錄提到中東部分案件因戰事而延遲，顯示專案時程存在不確定性。；**產能限制**：轉錄多次提到即使取得訂單，仍受限於公司供應與交期能力，屬營運風險。；**高投入成本**：美國設廠與在地團隊成本偏高，可能對短期獲利形成壓力。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
