          "detailMarkdown": "## 6903 巨漢 深度法說分析\n\n### 一頁結論\n- 展望評價：中性偏正面（65 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 3、保守訊號 1。\n- 判讀：方向偏正面，但管理層仍保留部分彈性，較適合追蹤接單、毛利率與下一季財測是否延續。 \n\n### 營運與財務重點\n- 1Q26 營收為新台幣 19.26 億元，季增 17.8%，年增 358.7%。\n- 1Q26 歸屬母公司淨利為 4.43 億元，EPS 為 6.72 元。\n- 1Q26 毛利率 31.4%、營業利益率 28.3%、淨利率 23.0%，皆較前一季與去年同期提升。\n- 截至 1Q26，總資產 56.06 億元、股東權益 37.12 億元，現金及約當現金 18.13 億元。\n- 1Q26 合約資產 15.35 億元、合約負債 5.07 億元，應收帳款週轉天數 48.1 天。\n\n### 展望與成長利基\n- 管理層表示截至 2026 年 5 月在手訂單約 110 億元，能見度約 2 至 3 年。\n- 2026 年 AI 相關營收占比預期將超過 60%，主要來自晶圓代工、先進封裝、AI 算力中心與研發中心。\n- 公共工程營收占比目標維持 20% 至 40%，作為穩定現金流與抗景氣循環支撐。\n- 長期目標為 2030 年前營收挑戰 100 億元，並維持業界領先利潤率。\n- 海外布局方面，會中提到已於 2025 年董事會通過美國設立分公司規劃，日本目前未揭露具體計畫。\n\n### 產品、客戶與市場位置\n- 公司主軸聚焦於 AI 基礎建設與公共工程雙引擎，強調高附加價值工程與穩健接案。\n- 管理層多次提到以 BIM、AI 自動建模、模組化預製與供應鏈整合提升效率。\n- 2026 年 AI 相關營收占比預期將超過 60%，主要來自晶圓代工、先進封裝、AI 算力中心與研發中心。\n- 海外布局方面，會中提到已於 2025 年董事會通過美國設立分公司規劃，日本目前未揭露具體計畫。\n- AI 與半導體相關需求雖強，但仍受產業循環與客戶投資時點變動影響。\n- 轉錄提及「2026 年 AI 相關營收占比超過 60%」與簡報第 15 頁一致。\n\n### 風險與不確定性\n- 工程案認列高度受建廠時程、專案進度與業主資本支出節奏影響。\n- AI 與半導體相關需求雖強，但仍受產業循環與客戶投資時點變動影響。\n- 缺工、供應鏈調度與原物料/施工成本波動，可能影響交期與毛利率。\n- 公司指出未來可能有可轉債資金募集，仍需留意股本稀釋與負債結構變化。\n- 簡報屬前瞻性資訊，實際結果可能與預期存在差異。\n- 轉錄中公司名稱多處寫作「聚和／聚漢／巨漢」，依簡報與 MOPS 資料應為「巨漢系統科技」；**需人工確認**轉錄來源是否為語音誤識。\n- 轉錄提到「EPS達6.72億」應為 **EPS 6.72 元**，與簡報數字一致；**需人工確認**轉錄口誤。\n- 轉錄提到「毛利率定估標在20%」與簡報顯示高毛利率策略、1Q26 毛利率 31.4% 的表述不一致；**需人工確認**語意是否為「成本／預估」相關說法。\n\n### Q&A 與管理層口氣\n- 管理層多次提到以 BIM、AI 自動建模、模組化預製與供應鏈整合提升效率。\n- 在手訂單規模維持高檔，管理層表示可支撐未來 2 至 3 年能見度。\n- 1Q26 毛利率 31.4%、營業利益率 28.3%、淨利率 23.0%，皆較前一季與去年同期提升。\n- 管理層表示截至 2026 年 5 月在手訂單約 110 億元，能見度約 2 至 3 年。\n- 缺工、供應鏈調度與原物料/施工成本波動，可能影響交期與毛利率。\n- 轉錄提到「毛利率定估標在20%」與簡報顯示高毛利率策略、1Q26 毛利率 31.4% 的表述不一致；**需人工確認**語意是否為「成本／預估」相關說法。\n\n### 評分利基點\n- 加分主因：2026 年第一季營運表現為公司成立以來最佳單季，營收、毛利與獲利均大幅成長。；公司主軸聚焦於 AI 基礎建設與公共工程雙引擎，強調高附加價值工程與穩健接案。；管理層多次提到以 BIM、AI 自動建模、模組化預製與供應鏈整合提升效率。。\n- 扣分或保留：工程案認列高度受建廠時程、專案進度與業主資本支出節奏影響。；AI 與半導體相關需求雖強，但仍受產業循環與客戶投資時點變動影響。；缺工、供應鏈調度與原物料/施工成本波動，可能影響交期與毛利率。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
