          "detailMarkdown": "## 1303 南亞 深度法說分析\n\n### 一頁結論\n- 展望評價：中性偏正面（57 分）。\n- 資料基礎：本次尚未取得可用語音轉錄，評估主要依簡報與 MOPS 擇要訊息；若後續補入影音，分數與判讀可再更新。\n- 評分依據：正向訊號 1、保守訊號 0。\n- 判讀：方向偏正面，但管理層仍保留部分彈性，較適合追蹤接單、毛利率與下一季財測是否延續。 \n\n### 營運與財務重點\n- 2026 年第一季合併營收為新台幣 686.0 億元，較 2025 年第四季與去年同期均增加。\n- 營業利益為新台幣 37.4 億元，較前一季及去年同期皆顯著成長，主因電子材料獲利提升。\n- 稅前淨利為新台幣 160.8 億元，受營業利益增加與權益法投資收益增加挹注。\n- EPS 為 1.80 元，簡報指出獲利動能來自南亞電子材料、南亞電路板及南亞科技等電子相關事業。\n- 營收結構中，2026 年第一季電子材料比重升至 52.8%，高於 2025 年第四季的 50.9%。\n\n### 展望與成長利基\n- 2026 年第二季電子材料需求仍強，簡報描述記憶體、ABF 載板與高階材料供應缺口持續存在。\n- 化工產品面臨原料供應不穩與行情波動，公司表示台灣與中國大陸地區採降量生產。\n- 美國德州乙二醇廠因上游原料供應穩定，維持全能生產並以外銷市場為主。\n- 聚酯產品因原料成本偏高、終端需求持平，成本轉嫁不易，採購動能偏觀望。\n- 塑膠加工產品受原料價格波動影響，下游備庫態度保守。\n\n### 產品、客戶與市場位置\n- AI、高效能運算、雲端基礎建設與邊緣運算需求，帶動中高階電子材料銷量與價格同步走升。\n- 公司持續推進擴建計畫，涵蓋台灣、中國大陸與美國多項產能與製程升級。\n- 化工產品面臨原料供應不穩與行情波動，公司表示台灣與中國大陸地區採降量生產。\n- 美國德州乙二醇廠因上游原料供應穩定，維持全能生產並以外銷市場為主。\n- 聚酯產品因原料成本偏高、終端需求持平，成本轉嫁不易，採購動能偏觀望。\n- 塑膠加工產品受原料價格波動影響，下游備庫態度保守。\n\n### 風險與不確定性\n- 石化產業受戰爭與地緣政治影響，原料供應不穩且價格波動大。\n- 能源成本與貴金屬價格維持高檔，可能持續影響電子材料與化工成本。\n- 終端消費需求回升仍不明朗，化工與聚酯產品需求修復速度有限。\n- 下游客戶備庫趨於保守，塑膠加工產品出貨動能可能受影響。\n- 轉投資收益對稅前淨利與 EPS 影響明顯，後續變動具不確定性。\n- **需人工確認：** 簡報第 9 頁「權益法投資收益增加 82.0 億元」與「南亞科技增加 43.8 億元、台塑石化增加 35.3 億元」加總為 79.1 億元，與 82.0 億元不一致。\n- **需人工確認：** 同頁英文版寫「FPCC +NT$3.53 bn」，與中文版「台塑石化增加 35.3 億元」一致，但若依小數四捨五入，與總增額仍有差異。\n- **需人工確認：** 簡報第 12 頁產品別營業利益佔比數字出現極端百分比，推測為格式或基期影響，需確認是否為佔比、年增率或其他定義。\n\n### Q&A 與管理層口氣\n- 公司持續推進擴建計畫，涵蓋台灣、中國大陸與美國多項產能與製程升級。\n- 會議議程涵蓋公司概況、財務狀況、2026 年第二季展望、擴建計畫與問答。\n- 聚酯產品因原料成本偏高、終端需求持平，成本轉嫁不易，採購動能偏觀望。\n- 能源成本與貴金屬價格維持高檔，可能持續影響電子材料與化工成本。\n\n### 評分利基點\n- 加分主因：公司聚焦於塑膠加工、化工、電子材料與聚酯四大事業，2026 年第一季營收成長主要由電子材料帶動。；AI、高效能運算、雲端基礎建設與邊緣運算需求，帶動中高階電子材料銷量與價格同步走升。；2026 年第一季 EPS 達 1.80 元，為近 15 季新高，主要來自本業電子材料與轉投資收益。。\n- 扣分或保留：石化產業受戰爭與地緣政治影響，原料供應不穩且價格波動大。；能源成本與貴金屬價格維持高檔，可能持續影響電子材料與化工成本。；終端消費需求回升仍不明朗，化工與聚酯產品需求修復速度有限。。\n- 可信度：尚缺語音轉錄，較難判斷管理層口氣、Q&A 細節與未寫在簡報中的展望。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
