            "**需人工確認**：簡報與逐字稿皆提到「2025 年銷售金額 32.22 億」，但財務表第 22、23 頁以 2025 全年度數字呈現為 3,222,227 千元，口徑一致但建議仍核對是否為合併營收。",
            "**需人工確認**：英文簡報第 8 頁提到「ISO 50001:2001」，與常見規格表述不一致，疑似排版或轉錄問題。",
            "**需人工確認**：逐字稿提到「海威子公司」作為折舊增加原因，簡報未明示此名稱，可能為口誤或轉錄誤字。",
            "**未揭露**：簡報未提供 2026 全年財測、訂單能見度數字、產能利用率或各廠區細部產能規模。"
