          "detailMarkdown": "## 6617 共信-KY 深度法說分析\n\n### 一頁結論\n- 展望評價：中性觀望（44 分）。\n- 資料基礎：本次尚未取得可用語音轉錄，評估主要依簡報與 MOPS 擇要訊息；若後續補入影音，分數與判讀可再更新。\n- 評分依據：正向訊號 0、保守訊號 1。\n- 判讀：目前資訊偏中性，正向題材與不確定因素並存，需等待更明確的量化指標。 \n\n### 營運與財務重點\n- 公司基本資料顯示實收資本額為新台幣 12.7 億元，研發中心位於新北市五股產業園區，產品生產地涉及台灣與中國天津。\n- 已開發成功產品：頭頸癌 H&N、中央型肺癌嚴重氣管阻塞；開發中產品：TACC、MPE、HCC、犬科黑色素瘤等。\n- 中國市場已提及取得藥品上市許可、進入商保資格、於 310 家以上醫院銷售、累計超過 2,000 次處方治療經驗。\n- 簡報未揭露本次法說的營收、獲利、現金流、毛利率或年度財務比較數據。\n- 產品在不同市場之銷售/授權進度以規劃與目標為主，未揭露明確財務貢獻拆分。\n\n### 展望與成長利基\n- 人體腫瘤方面，2027 年前推動中國核心區域三甲醫院准入 60 家以上，並持續擴大呼吸介入領域覆蓋。\n- 惡性胸腔積液規劃同步推進台灣、美國臨床試驗與中國 IIT 研究，並洽談國際藥廠授權合作。\n- 肝癌產品規劃於 2027 年展開多國多中心三期臨床，目標市場包含日本、台灣、中國、泰國、越南。\n- 寵物產品規劃台灣市場上市、擴大犬科/貓科適應症、啟動美國有條件上市與海外臨床合作。\n- 海外布局優先方向包括東南亞、北非，並延伸至美國、歐洲與其他地區。\n\n### 產品、客戶與市場位置\n- 公司主軸為腫瘤內注射/微創化學消融產品平台，核心品牌為人體用「普羅仙安」與動物用「思沛康」。\n- 人體產品聚焦中央型肺癌嚴重氣道阻塞，並延伸至惡性胸腔積液、肝癌、頭頸癌等適應症。\n- 動物產品聚焦犬科黑色素瘤，並延伸至馬科淺表腫瘤與其他寵物腫瘤應用。\n- 公司強調以臨床案例、回溯性研究與 IIT/臨床試驗推進產品開發與市場拓展。\n- 公司基本資料顯示實收資本額為新台幣 12.7 億元，研發中心位於新北市五股產業園區，產品生產地涉及台灣與中國天津。\n- 已開發成功產品：頭頸癌 H&N、中央型肺癌嚴重氣管阻塞；開發中產品：TACC、MPE、HCC、犬科黑色素瘤等。\n\n### 風險與不確定性\n- 多項產品仍處於臨床試驗、IIT、藥證申請或上市審查階段，時程存在不確定性。\n- 海外市場拓展仰賴各國法規、藥證審查、臨床資料接受度與合作夥伴進度。\n- 簡報中大量市場規模、滲透率與市占率假設，屬預估性資料，實際達成具不確定性。\n- 人體與動物產品均涉及多中心合作與跨國授權，執行節奏可能受法規、醫院收案及合作進度影響。\n- 臨床療效與安全性資料多為案例、回顧性研究或特定研究樣本，外推性仍需審慎看待。\n- 需人工確認：簡報第 4 頁「2026」與「2025」時程內容排列較密集，部分事件先後順序不易辨識。\n- 需人工確認：簡報第 9 頁頭頸癌、犬用產品、HCC、MPE 等產品里程碑時間點較多，部分年份與季度標示可能因排版造成錯位。\n- 需人工確認：簡報第 19、21、26 頁市場規模與患者數字，多為估算值，且部分欄位文字壓縮，需與原始版面逐一核對。\n\n### Q&A 與管理層口氣\n- 簡報未揭露本次法說的營收、獲利、現金流、毛利率或年度財務比較數據。\n\n### 評分利基點\n- 加分主因：公司強調以臨床案例、回溯性研究與 IIT/臨床試驗推進產品開發與市場拓展。；產品在不同市場之銷售/授權進度以規劃與目標為主，未揭露明確財務貢獻拆分。。\n- 扣分或保留：多項產品仍處於臨床試驗、IIT、藥證申請或上市審查階段，時程存在不確定性。；海外市場拓展仰賴各國法規、藥證審查、臨床資料接受度與合作夥伴進度。；簡報中大量市場規模、滲透率與市占率假設，屬預估性資料，實際達成具不確定性。。\n- 可信度：尚缺語音轉錄，較難判斷管理層口氣、Q&A 細節與未寫在簡報中的展望。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
