          "detailMarkdown": "## 8926 台汽電 深度法說分析\n\n### 一頁結論\n- 展望評價：中性觀望（50 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 0、保守訊號 0。\n- 判讀：目前資訊偏中性，正向題材與不確定因素並存，需等待更明確的量化指標。 \n\n### 營運與財務重點\n- 115Q1 合併營收 137.05 億元，營業淨利 11.58 億元，稅後淨利 17.85 億元，母公司業主淨利 15.43 億元，EPS 2.11 元。\n- 營收與獲利大幅成長，主因為森霸、星能、星元三家 IPP 併入合併，以及認列相關處分/廉價購買利益。\n- 115/3/31 合併資產總計 791.99 億元、負債總計 506.74 億元、權益 284.45 億元，負債比約 64.0%。\n- 115Q1 營業活動淨現金流入 21.61 億元，投資活動淨現金流量約 7.13 億元，籌資活動淨現金流入 48.20 億元，期末現金 97.91 億元。\n- 114 年 1~4 月合併營收 204.86 億元，其中銷貨收入 191.07 億元、研究諮詢及工程服務收入 13.79 億元。\n\n### 展望與成長利基\n- 官田廠短期將提高膠片與 SRF 等替代燃料比例，降低煤炭使用，並持續執行自主減量計畫。\n- 中長期將評估設備改善與機組更新改建，以因應淨零趨勢與減煤政策。\n- 民營電廠面向將持續提升機組可靠度與容量因數，並關注燃氣電廠混氫、混氨與 CCUS 等低碳技術。\n- 國光二期已取得台電 117 年商轉燃氣機組採購標案，並已簽署統包工程契約，現已取得工作許可證並施工中。\n- 再生能源與海外業務將持續推進，包括離岸風電陸上變電站工程、彰化/苗栗風場與漁電共生、地熱探勘，以及海外替代案評估。\n\n### 產品、客戶與市場位置\n- 營運面聚焦於官田廠低碳轉型、IPP 機組維護與 PPA 到期因應、再生能源與海外案場評估。\n- 再生能源與海外業務將持續推進，包括離岸風電陸上變電站工程、彰化/苗栗風場與漁電共生、地熱探勘，以及海外替代案評估。\n- 再生能源案場如苗栗風力重置、大屯山地熱、漁電共生等，均涉及許可、環評與施工進度風險。\n\n### 風險與不確定性\n- 菲律賓 RP Energy 燃煤電廠開發因當地中止新燃煤政策而暫緩，後續替代方案與退場可行性仍在評估。\n- 台電對公司轉投資民營電廠主張損害賠償案件仍在臺灣高等法院審理中。\n- 國光、星元、星能、森霸等 IPP 之 PPA 將於未來陸續到期，後續經營策略仍具不確定性。\n- 再生能源案場如苗栗風力重置、大屯山地熱、漁電共生等，均涉及許可、環評與施工進度風險。\n- 115Q1 受併購與一次性利益影響明顯，後續獲利結構仍需觀察常態化表現。\n- **需人工確認**：轉錄提及「東電持股的森霸電等三家 IPP 股權」；簡報寫明為向 **TEPCI B.V.** 收購森霸電力、星能電力、星元電力全數股權，名稱與交易對象表述不完全一致。\n- **需人工確認**：轉錄提及「購售電合約在 118 年會陸續到期」；簡報僅寫「PPA 到期之因應」，未逐一列示年份與對象。\n- **需人工確認**：轉錄稱 115Q1 合併營收「137億」、營業費用「3.24億元」、本期淨利「17.85億元」；與簡報數字大致相符，但語音中部分單位口語化，建議以簡報表格為準。\n\n### Q&A 與管理層口氣\n- **需人工確認**：轉錄稱 115Q1 合併營收「137億」、營業費用「3.24億元」、本期淨利「17.85億元」；與簡報數字大致相符，但語音中部分單位口語化，建議以簡報表格為準。\n\n### 評分利基點\n- 加分主因：營收與獲利大幅成長，主因為森霸、星能、星元三家 IPP 併入合併，以及認列相關處分/廉價購買利益。；官田廠短期將提高膠片與 SRF 等替代燃料比例，降低煤炭使用，並持續執行自主減量計畫。；中長期將評估設備改善與機組更新改建，以因應淨零趨勢與減煤政策。。\n- 扣分或保留：菲律賓 RP Energy 燃煤電廠開發因當地中止新燃煤政策而暫緩，後續替代方案與退場可行性仍在評估。；台電對公司轉投資民營電廠主張損害賠償案件仍在臺灣高等法院審理中。；國光、星元、星能、森霸等 IPP 之 PPA 將於未來陸續到期，後續經營策略仍具不確定性。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
