          "detailMarkdown": "## 1473 台南 深度法說分析\n\n### 一頁結論\n- 展望評價：中性觀望（50 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 0、保守訊號 0。\n- 判讀：目前資訊偏中性，正向題材與不確定因素並存，需等待更明確的量化指標。 \n\n### 營運與財務重點\n- 2026Q1合併營收為 **NT$19.59億元**，年減 **21.51%**。\n- 2026Q1毛利為 **NT$3.60億元**，營業利益 **NT$1.03億元**，稅前淨利 **NT$1.23億元**，稅後淨利 **NT$1.00億元**。\n- 2026Q1每股盈餘（EPS）為 **0.69元**；毛利率 **18.38%**、營業利益率 **5.27%**、淨利率 **6.26%**。\n- 2025全年營收 **NT$66.78億元**，稅後淨利 **NT$0.83億元**，EPS **0.57元**。\n- 簡報揭示 2022–2026Q1 歷年財務表，顯示 2024 年表現相對較佳，2025 年獲利下滑。\n\n### 展望與成長利基\n- 印尼第三廠規劃持續進行中，屬未來產能布局之一。\n- 公司持續以多國據點配置，強調成本效率、低關稅與供應鏈競爭力。\n- 簡報未揭露具體接單展望、營收成長目標或財測。\n- 公司表示未發布財務預測，未來營運仍受市場需求、價格、匯率與供應鏈因素影響。\n\n### 產品、客戶與市場位置\n- 公司定位為以服裝製造為主的代工廠，主要客戶為美國、加拿大、日本等品牌。\n- 轉錄提及產品結構以女裝與下裝為主，銷售區域以美國為大宗。\n- 公司說明目前在中國、印尼、柬埔寨、越南及台灣設有營運據點，另有印尼第三廠計畫進行中。\n- 公司表示未發布財務預測，未來營運仍受市場需求、價格、匯率與供應鏈因素影響。\n- 簡報免責聲明提及：市場需求變化、價格波動、競爭行為、國際經濟狀況與匯率波動等，均可能影響實際結果。\n- 其他公司沿革、產能分布與產品別圖表已在簡報揭示，但未有進一步口頭補充。\n\n### 風險與不確定性\n- 簡報免責聲明提及：市場需求變化、價格波動、競爭行為、國際經濟狀況與匯率波動等，均可能影響實際結果。\n- 上下游供應鏈變動與外部環境風險，可能使實際營運與簡報敘述不同。\n- 轉錄提到公司擁有第三方認證，但未細列各廠最新驗證範圍與有效期限。\n- 海外產能分散雖有助營運彈性，但也可能涉及跨國管理與產能調配不確定性。\n- **需人工確認：淨利率數字不一致。**\n- 簡報頁15顯示 2026Q1 淨利率為 **6.26%**。\n- 轉錄口述提到 2026Q1 淨利率為 **16.26%**，與簡報不符。\n- **需人工確認：產品別/性別占比口述與簡報圖表未見完整數值對照。**\n\n### Q&A 與管理層口氣\n- 本次轉錄顯示現場進入提問環節，但未記錄到實際問答內容。\n- 公司治理評鑑於第12屆（2025年）結果：總分 **85.99分**，落於上市公司 **36%–50%** 區間。\n- 市值50億元以下組別排名級距落在 **11%–20%** 區間。\n- 2025年股利為 **每股現金股利0.5元**，股利配發率 **87.72%**。\n- 其他公司沿革、產能分布與產品別圖表已在簡報揭示，但未有進一步口頭補充。\n\n### 評分利基點\n- 加分主因：簡報與轉錄一致強調公司未發布財務預測，相關前瞻敘述不構成保證。；公司持續以多國據點配置，強調成本效率、低關稅與供應鏈競爭力。；簡報未揭露具體接單展望、營收成長目標或財測。。\n- 扣分或保留：簡報免責聲明提及：市場需求變化、價格波動、競爭行為、國際經濟狀況與匯率波動等，均可能影響實際結果。；上下游供應鏈變動與外部環境風險，可能使實際營運與簡報敘述不同。；轉錄提到公司擁有第三方認證，但未細列各廠最新驗證範圍與有效期限。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
