          "detailMarkdown": "## 4766 南寶 深度法說分析\n\n### 一頁結論\n- 展望評價：正面看好（78 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 4、保守訊號 0。\n- 判讀：正向訊號較集中，通常代表公司對需求、訂單或產品組合的能見度較高。仍要確認這些動能是否能轉成營收與毛利。 \n\n### 營運與財務重點\n- 1Q26 毛利率 35.1%，高於 1Q25 的 34.4%；營業利益率 17.6%，年增 1.2 個百分點。\n- 歸屬母公司淨利 7.90 億元，EPS 6.55 元，年增 8%。\n- 1Q26 產品結構中，接著劑占營收 68%，塗料與建材 26%，其他 6%。\n- 資產負債表顯示現金 85.33 億元、總資產 294.31 億元，維持淨現金部位。\n- 2025 年全年營收 232.00 億元、稅後淨利 24.42 億元、EPS 20.25 元。\n\n### 展望與成長利基\n- 2026 年營收目標為續創歷史新高；鞋材業務持續爭取市占，並開發新產品與新應用。\n- 半導體先進封裝高階膠材合作進展順利，預期認證推進下，全年營收貢獻逐步提升。\n- 接著劑以外業務方面，工業與消費性應用仍偏保守，但公司看好半導體、電子、木工、紡織等領域的成長。\n- 塗料與建材方面，澳洲建材需求回升、匯率具正面效果；塗料則聚焦政府基建、AI 基建與消費電子應用。\n- 公司提到將持續優化產品結構，並朝費用率長期低於 15% 的方向努力。\n\n### 產品、客戶與市場位置\n- 半導體特化與電子應用被列為新成長動能，已開始對合資公司出貨並認列營收。\n- 管理層多次強調 ROE 長期目標 20% 以上，並持續透過產品組合與費用率改善提升效率。\n- 法說中亦說明 ESG、公司治理與永續產品進展，綠色產品營收占比公司初步估計為 72%。\n- 1Q26 產品結構中，接著劑占營收 68%，塗料與建材 26%，其他 6%。\n- 2026 年營收目標為續創歷史新高；鞋材業務持續爭取市占，並開發新產品與新應用。\n- 半導體先進封裝高階膠材合作進展順利，預期認證推進下，全年營收貢獻逐步提升。\n\n### 風險與不確定性\n- 全球政經情勢與消費景氣不確定，鞋材需求仍偏保守。\n- 原物料與油價波動會影響成本，毛利率短期可能承壓。\n- 客戶調價機制與原料成本反映存在時間差，部分影響可能延後顯現。\n- 半導體相關新業務仍在認證與放量階段，實際放量時點具不確定性。\n- 海外擴產與新廠建設存在執行與時程風險。\n- **需人工確認**：語音轉錄多處將「新寳紘」與簡報中的「Advanced Pao Trusval Technology／新寳紘科技」交錯使用，名稱基本一致但英文/中文對應建議再核。\n- **需人工確認**：轉錄提到「3 月份創入歷史新高 23 億」與簡報僅揭露 1Q26 季度營收 58.36 億，月營收數字未在簡報中列示。\n- **需人工確認**：轉錄中部分用語如「CCO認證」疑似口誤，簡報內容對應較可能是客戶認證／封裝認證進度。\n\n### Q&A 與管理層口氣\n- 管理層多次強調 ROE 長期目標 20% 以上，並持續透過產品組合與費用率改善提升效率。\n- 1Q26 毛利率 35.1%，高於 1Q25 的 34.4%；營業利益率 17.6%，年增 1.2 個百分點。\n- 公司提到將持續優化產品結構，並朝費用率長期低於 15% 的方向努力。\n- 原物料與油價波動會影響成本，毛利率短期可能承壓。\n- 客戶調價機制與原料成本反映存在時間差，部分影響可能延後顯現。\n- **需人工確認**：轉錄提到印度新廠「明年度做到 3 億多台幣」與簡報僅揭露建廠與產能方向，未見相同數字。\n\n### 評分利基點\n- 加分主因：2026 年第 1 季營收新台幣 58.36 億元，年增 5%，季減 2%，整體營運維持成長。；公司表示今年目標仍是「營收再創歷史新高」，並持續推動 NextGen 成長策略。；半導體特化與電子應用被列為新成長動能，已開始對合資公司出貨並認列營收。。\n- 扣分或保留：全球政經情勢與消費景氣不確定，鞋材需求仍偏保守。；原物料與油價波動會影響成本，毛利率短期可能承壓。；客戶調價機制與原料成本反映存在時間差，部分影響可能延後顯現。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
