          "detailMarkdown": "## 4442 竣邦-KY 深度法說分析\n\n### 一頁結論\n- 展望評價：中性偏正面（57 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 1、保守訊號 0。\n- 判讀：方向偏正面，但管理層仍保留部分彈性，較適合追蹤接單、毛利率與下一季財測是否延續。 \n\n### 營運與財務重點\n- 2026 Q1 合併營收 **4.37 億元**，年增 **6.5%**；毛利率 **27%**，較去年同期下降約 2 個百分點。\n- 2026 Q1 稅後淨利 **3,719 萬元**，EPS **1.17 元**；公司說明 EPS 受 **股數增加**與 **稅率上升**影響。\n- 產品/應用別中，2025 年營收合計 **16.71 億元**，較 2024 年成長；2026 Q1 合計 **4.37 億元**。\n- 資產負債表顯示 2026 Q1 總資產 **13.27 億元**、股東權益 **9.22 億元**、負債比 **30.51%**。\n- 2025 年現金股利 **3.50 元**，配發率 **67%**；簡報與轉錄均提到過往配發率多維持在相對高水位。\n\n### 展望與成長利基\n- 公司引用市場資料指出，全球運動服飾市場 2024–2030 年 CAGR 約 **6%–8%**，2030 年市場規模估 **3,000 億美元**。\n- 管理層認為 **品牌供應商集中化**與**供應基地移轉至東南亞**，有利於具規模與研發能力的供應商承接訂單。\n- **越南二廠**被定位為提升區域產能、完善供應鏈彈性與接單能力的重要布局。\n- 產品面持續推進 **PFAS Free**、**T2T 回收技術**與複合機能材料等永續/高機能應用。\n- 公司提到 **Nike SKIMS、ITOCHU、Tumi、NO BULL** 等合作與新客戶開發，並對 **2026 年維持雙位數成長**的方向表達正向看法。\n\n### 產品、客戶與市場位置\n- 集團布局以 **台灣為品牌接單與研發中心**，中國與越南為供應鏈生產管理與產品開發據點。\n- 2026 年營運主軸聚焦在 **運動、戶外、滑雪/衝浪**等機能布料市場，以及供應鏈區域化帶來的接單機會。\n- 管理層於會中提到，全年展望仍維持成長基調，並強調新客戶與既有品牌合作持續推進。\n- 產品/應用別中，2025 年營收合計 **16.71 億元**，較 2024 年成長；2026 Q1 合計 **4.37 億元**。\n- 公司引用市場資料指出，全球運動服飾市場 2024–2030 年 CAGR 約 **6%–8%**，2030 年市場規模估 **3,000 億美元**。\n- **越南二廠**被定位為提升區域產能、完善供應鏈彈性與接單能力的重要布局。\n\n### 風險與不確定性\n- 公司於免責聲明中指出，未來營運可能受 **外部風險與不確定因素**影響，實際結果可能與預測差異。\n- 轉錄提到 **匯率因素**會影響毛利率，尤其是 **美元兌人民幣**的變動。\n- **產品組合變化**會影響毛利率；2026 Q1 運動類占比下降、戶外與滑雪/衝浪比重上升。\n- **越南二廠建置進度**與產能爬升時程，仍屬後續營運變數。\n- 國際關稅、地緣政治、品牌供應鏈調整與客戶下單時點，皆可能造成訂單波動。\n- **需人工確認**：簡報第 5 頁寫「**2021年7月27日**成立」，轉錄提到「**2021年成立了 PWI 的這個架構**」，名詞 **PWI** 未見於簡報，疑為口誤或轉錄誤植。\n- **需人工確認**：簡報第 22 頁實收資本額/股本為 **321,840 千元**，第 5 頁則寫 **323,056 千元**（截至 2026/4/30）；兩者可能因基準日不同，仍建議確認。\n- **需人工確認**：簡報第 10 頁產品結構寫 **平織 88%、針織 4%、其他 8%**，英文版寫 **87.99%**；屬四捨五入差異，無重大衝突。\n\n### Q&A 與管理層口氣\n- Q：2026 Q1 運動類營收占比下滑原因？\n- Q：第二季運動類占比與毛利率看法？\n- Q：第二季營收動能是否偏弱？\n- Q：有效稅率後續走勢？\n- 其他：公司重申數位化產品解決方案，包括 **布料資料庫、3D 模擬、雲端選布平台**，用於提升開發效率與客戶決策效率。\n\n### 評分利基點\n- 加分主因：管理層於會中提到，全年展望仍維持成長基調，並強調新客戶與既有品牌合作持續推進。；產品/應用別中，2025 年營收合計 **16.71 億元**，較 2024 年成長；2026 Q1 合計 **4.37 億元**。；2025 年現金股利 **3.50 元**，配發率 **67%**；簡報與轉錄均提到過往配發率多維持在相對高水位。。\n- 扣分或保留：公司於免責聲明中指出，未來營運可能受 **外部風險與不確定因素**影響，實際結果可能與預測差異。；轉錄提到 **匯率因素**會影響毛利率，尤其是 **美元兌人民幣**的變動。；**產品組合變化**會影響毛利率；2026 Q1 運動類占比下降、戶外與滑雪/衝浪比重上升。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
