          "detailMarkdown": "## 8121 越峰 深度法說分析\n\n### 一頁結論\n- 展望評價：中性偏正面（64 分）。\n- 資料基礎：本次評估優先依語音轉錄內容，再與簡報重點交叉比對；若轉錄與簡報數字不一致，以簡報揭露口徑為主。\n- 評分依據：正向訊號 2、保守訊號 0。\n- 判讀：方向偏正面，但管理層仍保留部分彈性，較適合追蹤接單、毛利率與下一季財測是否延續。 \n\n### 營運與財務重點\n- 2026Q1 合併營收 8.53 億元，年增 18.6%。\n- 2026Q1 合併毛利 1.66 億元，毛利率 19.5%，年增主要來自產品組合優化。\n- 2026Q1 營業淨利 2,500 萬元，營業利益率 2.9%。\n- 2026Q1 稅後淨利 1,300 萬元，歸屬母公司業主淨利 2,200 萬元，EPS 0.10 元。\n- 財務比率顯示流動比率、速動比率較前期改善；負債占資產比率約 51%。\n\n### 展望與成長利基\n- 軟性鐵氧磁鐵芯：AI 伺服器、資料中心相關應用持續成長。\n- SiC N-type：用於電動車、充電設備、再生能源與 AI 伺服器電源架構，已進入送樣與擴產。\n- SiC 半絕緣：對應 RF、高頻、高耐壓與部分 AR/VR、先進通訊應用，需求被描述為增加中。\n- 公司表示將持續投入高附加價值產品、材料開發與客戶認證。\n- 轉錄指出未來重點將聚焦 AI、機器人、自動駕駛等可能帶動的新應用。\n\n### 產品、客戶與市場位置\n- 軟性鐵氧磁鐵芯受 AI 應用帶動，資料中心、通用伺服器與 AI 伺服器需求增加。\n- SiC 事業聚焦高純度粉體、燒結體及相關半導體/工業應用，並持續送樣驗證。\n- 2026Q1 合併毛利 1.66 億元，毛利率 19.5%，年增主要來自產品組合優化。\n- 軟性鐵氧磁鐵芯：AI 伺服器、資料中心相關應用持續成長。\n- SiC N-type：用於電動車、充電設備、再生能源與 AI 伺服器電源架構，已進入送樣與擴產。\n- 公司表示將持續投入高附加價值產品、材料開發與客戶認證。\n\n### 風險與不確定性\n- 中國及海外電動車市場需求波動，影響 SiC N-type 與車用相關需求。\n- 轉錄提到廣州子公司高新技術企業資格被取消，導致補稅與相關費用認列。\n- 資本支出與折舊持續增加，後續效益仍仰賴產能利用與產品組合。\n- SiC 與 AI 伺服器需求雖提升，但客戶庫存調整會造成短期出貨波動。\n- 市場競爭與價格壓力仍存在，特別是 SiC 相關領域。\n- **需人工確認**：簡報寫法多處為「越峯電子」，轉錄口語多次說成「月峰」，應確認公司名稱口語辨識是否正確。\n- **需人工確認**：簡報第 14 頁表格數字排版混雜，轉錄口語補充的 2026Q1 營收、毛利、EPS 等數字與簡報大致一致，但仍建議核對原始表格欄位對應。\n- **需人工確認**：轉錄提到「高技資格被取消」應為廣州子公司高新技術企業資格，與財務損失來源需再確認正式用語。\n\n### Q&A 與管理層口氣\n- 公司表示長期借款、財務成本與資金配置目前可控，未規劃發債，增資則視未來大額資本支出而定。\n- 目前 SiC 粉體產能：N-type 約 20 噸，半絕緣約 1 噸；另有氮化鋁與其他材料開發。\n- 管理層表示 AI 資料中心、高頻低損耗材料、HVDC 800V 供電架構皆已有供貨或送樣。\n- 轉錄中提到 SiC 相關產品占比約 16%~18%。\n- 產能利用率轉錄提到：矽晶體/相關主業約 9 成，SiC 約 5~6 成。\n\n### 評分利基點\n- 加分主因：轉錄提到 2026Q1 合併營收 8.53 億元，較 2025Q1 成長。；軟性鐵氧磁鐵芯受 AI 應用帶動，資料中心、通用伺服器與 AI 伺服器需求增加。；SiC 事業聚焦高純度粉體、燒結體及相關半導體/工業應用，並持續送樣驗證。。\n- 扣分或保留：中國及海外電動車市場需求波動，影響 SiC N-type 與車用相關需求。；轉錄提到廣州子公司高新技術企業資格被取消，導致補稅與相關費用認列。；資本支出與折舊持續增加，後續效益仍仰賴產能利用與產品組合。。\n- 可信度：已取得語音轉錄，能看到管理層在簡報外的補充與 Q&A；但專有名詞與口述數字仍需以簡報或公告交叉確認。\n\n### 後續追蹤清單\n- 下一次更新優先比對本次展望是否落實為營收、毛利率或接單成長。 \n- 追蹤財務數字是否只是單季改善，或能延續成全年趨勢。 \n- 留意保守訊號是否擴大，例如成本、需求遞延、區域調整或公司未量化的部分。 \n- 此評分是法說內容品質與展望強弱的閱讀輔助，不等同買賣建議。"
